    parsed_result = {}
    if target_format == 'json':
        try:
            parsed_result = json.loads(target_text)
        except Exception as exception_info:
            _error('could not load target data, got: %s' % exception_info)
    elif target_format in ('yaml', 'yml'):
        try:
            import yaml
            try:
                parsed_result = yaml.load(target_text)
            except Exception as exception_info:
                _error('could not load target data, got: %s' % exception_info)
        except ImportError:
