**6. `Assign.glomit`**
```python
def glomit(self, target, scope):
    resolved_value = None
    if type(self.val) is Spec:
        resolved_value = scope[glom](target, self.val, scope)
    else:
        resolved_value = self.val

    operation_code = self.op
    argument_value = self.arg
    destination_path = self.path

    if self.path.startswith(S):
        source_target = scope[UP]
        destination_path_resolved = self.path.from_t()
    else:
        source_target = target
        destination_path_resolved = self.path

    destination_object = None
    try:
        destination_object = scope[glom](source_target, destination_path_resolved, scope)
    except PathAccessError as access_error:
        if not self.missing:
            raise

        unresolved_segment = self._orig_path[access_error.part_idx + 1:]
        missing_value = self.missing()
        assignment_spec = Assign(unresolved_segment, resolved_value, missing=missing_value)
        resolved_value = scope[glom](missing_value, assignment_spec, scope)

        original_operation, original_argument = self._orig_path.items()[access_error.part_idx]
        operation_code = original_operation
        argument_value = original_argument
        truncated_path = self._orig_path[:access_error.part_idx]
        destination_object = scope[glom](source_target, truncated_path, scope)

    # TODO: forward-detect immutable dest?
    if operation_code == '[':
        destination_object[argument_value] = resolved_value
    elif operation_code == '.':
        setattr(destination_object, argument_value, resolved_value)
    elif operation_code == 'P':
        handler_method = scope[TargetRegistry].get_handler('assign', destination_object)
        try:
            handler_method(destination_object, argument_value, resolved_value)
        except Exception as assignment_exception:
            raise PathAssignError(assignment_exception, truncated_path, argument_value)

    return target
